package vn.rtr.aeris.phone07;
import java.nio.file.*;import java.nio.channels.*;import java.nio.*;import java.io.*;import java.util.*;
/** Bounded immutable mock evidence. Publication requires a separate journal commit. */
public final class PayloadFiles07{
 public static final long MAX=12*1024*1024;public static final int MAX_RECORDS=96,MAX_IMAGE=524288;
 private final Path root,media;private final DraftStore journal;private final DraftStore.Fault fault;
 public PayloadFiles07(Path p)throws IOException{this(p,x->{});}public PayloadFiles07(Path p,DraftStore.Fault f)throws IOException{root=p;fault=f;journal=new DraftStore(p.resolve("journal"),f);media=p.resolve("media");if(Files.isSymbolicLink(media))throw new IOException("MEDIA_SYMLINK");Files.createDirectories(media);usage();}
 public synchronized DraftStore.Snapshot load()throws IOException{return journal.load();}
 public synchronized List<DraftStore.Snapshot> history()throws IOException{DraftStore.Snapshot s=journal.load();return journal.history(s==null?"ROOT":s.token);}
 public synchronized boolean pending()throws IOException{return journal.pending();}
 public synchronized DraftStore.Snapshot append(String expected,byte[]record)throws IOException{if(record.length>70000)throw new IOException("PAYLOAD_RECORD_BOUND");if(journal.history(expected).size()>=MAX_RECORDS||usage()+record.length+1024>MAX)throw new IOException("PAYLOAD_QUOTA_NO_DELETE");return journal.save(expected,record);}
 public synchronized long usage()throws IOException{long total=0;try(java.util.stream.Stream<Path>s=Files.walk(root)){for(Iterator<Path>i=s.iterator();i.hasNext();){Path p=i.next();if(Files.isSymbolicLink(p))throw new IOException("PAYLOAD_SYMLINK");if(Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS))total+=Files.size(p);else if(!Files.isDirectory(p,LinkOption.NOFOLLOW_LINKS))throw new IOException("PAYLOAD_MEMBER_TYPE");if(total>MAX)throw new IOException("PAYLOAD_EXISTING_QUOTA");}}return total;}
 private Path capture(String id)throws IOException{if(!id.matches("capture-[a-f0-9-]{36}"))throw new IOException("CAPTURE_ID");Path p=media.resolve(id);if(Files.isSymbolicLink(p))throw new IOException("CAPTURE_SYMLINK");return p;}
 private static final String[]NAMES={"original.jpg","sidecar.json","manifest.json","gateway.json"};
 public synchronized Map<String,String> put(String id,byte[][]bytes)throws IOException{if(bytes.length!=4||bytes[0].length<20||bytes[0].length>MAX_IMAGE)throw new IOException("CAPTURE_BOUND");long count;try(java.util.stream.Stream<Path>s=Files.list(media)){count=s.count();}if(count>=8)throw new IOException("CAPTURE_QUOTA_NO_DELETE");long size=0;for(int i=0;i<4;i++){size+=bytes[i].length;if(i>0&&bytes[i].length>32768)throw new IOException("JSON_BOUND");}if(usage()+size+71024>MAX)throw new IOException("CAPTURE_QUOTA_NO_DELETE");Path p=capture(id);Files.createDirectory(p);Map<String,String>hashes=new LinkedHashMap<>();for(int i=0;i<4;i++){try(FileChannel c=FileChannel.open(p.resolve(NAMES[i]),StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS)){ByteBuffer b=ByteBuffer.wrap(bytes[i]);while(b.hasRemaining())if(c.write(b)==0)throw new IOException("SHORT_WRITE");c.force(true);}hashes.put(NAMES[i],DraftStore.hash(bytes[i]));fault.at("MEDIA_"+i);}sync(p);sync(media);fault.at("MEDIA_DURABLE");return hashes;}
 private void sync(Path p)throws IOException{try(FileChannel c=FileChannel.open(p,StandardOpenOption.READ)){c.force(true);}}
 public synchronized byte[] read(String id,String name,String hash)throws IOException{if(!Arrays.asList(NAMES).contains(name)||!hash.matches("[a-f0-9]{64}"))throw new IOException("CAPTURE_MEMBER_ID");Path p=capture(id).resolve(name);int max=name.equals("original.jpg")?MAX_IMAGE:32768;if(Files.isSymbolicLink(p)||!Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)||Files.size(p)>max)throw new IOException("CAPTURE_MEMBER_BOUND");byte[]b;try(FileChannel c=FileChannel.open(p,StandardOpenOption.READ,LinkOption.NOFOLLOW_LINKS);ByteArrayOutputStream out=new ByteArrayOutputStream()){ByteBuffer block=ByteBuffer.allocate(4096);while(c.read(block)>0){block.flip();if(out.size()+block.remaining()>max)throw new IOException("CAPTURE_GROWING_FILE");out.write(block.array(),0,block.remaining());block.clear();}b=out.toByteArray();}if(b.length>max||!DraftStore.hash(b).equals(hash))throw new IOException("CAPTURE_HASH");return b;}
 public synchronized List<String> directories()throws IOException{List<String>r=new ArrayList<>();try(DirectoryStream<Path>s=Files.newDirectoryStream(media)){for(Path p:s)r.add(p.getFileName().toString());}return r;}
}
